// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	out, _ := s.InvoicePage(orgID, f, nil, math.MaxInt)
	return out
}

// InvoiceKey is a position in the invoice order: an invoice's creation time and ID.
type InvoiceKey struct {
	CreatedAt time.Time
	ID        string
}

// InvoicePage returns up to limit of an organization's invoices that match f, oldest first (ties by ID), starting with the
// first one after the position after (or the first one when after is nil). more reports whether a matching invoice follows
// the page.
func (s *Store) InvoicePage(orgID string, f InvoiceFilter, after *InvoiceKey, limit int) (items []Invoice, more bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	ids := s.invoiceIdx[orgID]
	start := 0
	if after != nil {
		start = sort.Search(len(ids), func(i int) bool { return after.before(s.invoices[ids[i]]) })
	}
	items = []Invoice{}
	for _, id := range ids[start:] {
		inv := s.invoices[id]
		if !f.matches(inv) {
			continue
		}
		if len(items) == limit {
			return items, true
		}
		items = append(items, cloneInvoice(inv))
	}
	return items, false
}

// before reports whether the position comes before inv in the invoice order.
func (k InvoiceKey) before(inv Invoice) bool {
	return k.CreatedAt.Before(inv.CreatedAt) || (k.CreatedAt.Equal(inv.CreatedAt) && k.ID < inv.ID)
}

func (f InvoiceFilter) matches(inv Invoice) bool {
	return (f.CustomerID == "" || inv.CustomerID == f.CustomerID) && (f.SubscriptionID == "" || inv.SubscriptionID == f.SubscriptionID) && (f.Status == "" || inv.Status == f.Status)
}

// indexInvoice adds a stored invoice to its organization's index in order. The caller holds the lock.
func (s *Store) indexInvoice(inv Invoice) {
	ids := s.invoiceIdx[inv.OrgID]
	i := sort.Search(len(ids), func(i int) bool { return InvoiceKey{inv.CreatedAt, inv.ID}.before(s.invoices[ids[i]]) })
	ids = append(ids, "")
	copy(ids[i+1:], ids[i:])
	ids[i] = inv.ID
	s.invoiceIdx[inv.OrgID] = ids
}

// rebuildInvoiceIndex indexes every stored invoice. The caller holds the lock, or the store is not yet shared.
func (s *Store) rebuildInvoiceIndex() {
	s.invoiceIdx = map[string][]string{}
	for id, inv := range s.invoices {
		s.invoiceIdx[inv.OrgID] = append(s.invoiceIdx[inv.OrgID], id)
	}
	for _, ids := range s.invoiceIdx {
		sort.Slice(ids, func(i, j int) bool {
			a, b := s.invoices[ids[i]], s.invoices[ids[j]]
			return InvoiceKey{a.CreatedAt, a.ID}.before(b)
		})
	}
}

