package api_test

import (
	"fmt"
	"net/http"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// TestZZTiming is a temporary measurement, reported through a failure message.
func TestZZTiming(t *testing.T) {
	e := apitest.New(t)
	now := e.Clock.Now()
	customers := []string{}
	for i := 0; i < 5000; i++ {
		c, err := e.Store.CreateCustomer(e.Acme.ID, fmt.Sprintf("Customer %d", i), fmt.Sprintf("c%d@acme.example", i), now)
		if err != nil {
			t.Fatal(err)
		}
		customers = append(customers, c.ID)
	}
	other, _ := e.Store.CreateCustomer(e.Globex.ID, "G", "g@globex.example", now)
	start := time.Now()
	for i := 0; i < 60000; i++ {
		if _, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: customers[i%len(customers)], Currency: money.USD,
			Lines: []store.Line{{Description: "Seat", Quantity: 1, UnitAmount: 500}}}, now.Add(time.Duration(i/3)*time.Second)); err != nil {
			t.Fatal(err)
		}
		if i%2 == 0 {
			if _, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Globex.ID, CustomerID: other.ID, Currency: money.USD,
				Lines: []store.Line{{Description: "G", Quantity: 1, UnitAmount: 5}}}, now); err != nil {
				t.Fatal(err)
			}
		}
	}
	created := time.Since(start)
	out := fmt.Sprintf("create 90000 invoices: %v\n", created)
	queries := []string{"", "?customer_id=" + customers[7], "?status=void", "?subscription_id=none", "?customer_id=" + customers[7] + "&status=open"}
	for _, q := range queries {
		var worst time.Duration
		cursor := ""
		for page := 0; page < 3; page++ {
			path := "/v1/invoices" + q + "?limit=100"
			if cursor != "" {
				path = "/v1/invoices" + q + "&limit=100&cursor=" + cursor
			}
			s := time.Now()
			r := e.Do("GET", path, e.Acme.Key, nil)
			d := time.Since(s)
			if d > worst {
				worst = d
			}
			if r.Code != http.StatusOK {
				t.Fatalf("status %d", r.Code)
			}
			m := r.Map(t)
			next, _ := m["next_cursor"].(string)
			if next == "" {
				break
			}
			cursor = next
		}
		out += fmt.Sprintf("query %-60q worst page %v\n", q, worst)
	}
	// First page from the very start, as a fresh client would see it.
	s := time.Now()
	e.Do("GET", "/v1/invoices?limit=100", e.Acme.Key, nil)
	out += fmt.Sprintf("first page unfiltered %v\n", time.Since(s))
	t.Fatalf("TIMINGS\n%s", out)
}

