package api

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"net/http"
	"os"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// TestZZBaselineDump is a temporary check: it writes every invoice list answer for a seeded dataset to $BASELINE_OUT.
func TestZZBaselineDump(t *testing.T) {
	out := os.Getenv("BASELINE_OUT")
	if out == "" {
		t.Skip("no BASELINE_OUT")
	}
	e := apitest.New(t)
	rng := rand.New(rand.NewSource(42))
	var log []string
	add := func(path string, r *apitest.Response) {
		log = append(log, fmt.Sprintf("%s -> %d %s", path, r.Code, r.Body.String()))
	}
	for _, org := range []apitest.Org{e.Acme, e.Globex, e.Acme} {
		_ = org
	}
	type ctx struct {
		org  apitest.Org
		cust []store.Customer
		subs []string
	}
	var orgs []ctx
	for _, org := range []apitest.Org{e.Acme, e.Globex} {
		c := ctx{org: org}
		for i := 0; i < 40; i++ {
			c.cust = append(c.cust, e.CreateCustomer(org, fmt.Sprintf("Cust %d", i), fmt.Sprintf("c%d@%s.example", i, org.ID)))
		}
		for i := 0; i < 5; i++ {
			c.subs = append(c.subs, fmt.Sprintf("sub_fake_%d_%s", i, org.ID))
		}
		orgs = append(orgs, c)
	}
	base := e.Clock.Now()
	n := 0
	for round := 0; round < 3000; round++ {
		// Timestamps repeat (ties), sometimes go backwards, sometimes move on.
		at := base.Add(time.Duration(rng.Intn(400)) * time.Second)
		for _, c := range orgs {
			if rng.Intn(3) == 0 {
				continue
			}
			cu := c.cust[rng.Intn(len(c.cust))]
			inv := store.Invoice{OrgID: c.org.ID, CustomerID: cu.ID, Currency: money.USD,
				Lines: []store.Line{{Description: fmt.Sprintf("line %d", n), Quantity: int64(1 + rng.Intn(3)), UnitAmount: int64(rng.Intn(10000))}}}
			if rng.Intn(4) == 0 {
				inv.SubscriptionID = c.subs[rng.Intn(len(c.subs))]
			}
			created, err := e.Store.CreateInvoice(inv, at)
			if err != nil {
				t.Fatal(err)
			}
			n++
			switch rng.Intn(6) {
			case 0:
				_, _ = e.Store.UpdateInvoice(c.org.ID, created.ID, func(i *store.Invoice) error {
					i.Status = store.InvoicePaid
					p := at
					i.PaidAt = &p
					return nil
				})
			case 1:
				_, _ = e.Store.UpdateInvoice(c.org.ID, created.ID, func(i *store.Invoice) error {
					i.Status = store.InvoiceVoid
					p := at
					i.VoidedAt = &p
					return nil
				})
			}
		}
	}
	// A customer of Globex used in Acme's queries, and a deleted-looking unknown id.
	queries := []string{"", "?customer_id=nope", "?subscription_id=nope", "?status=bogus", "?status=open", "?status=paid", "?status=void"}
	for _, c := range orgs {
		for _, cu := range c.cust[:6] {
			queries = append(queries, "?customer_id="+cu.ID, "?customer_id="+cu.ID+"&status=open")
		}
		for _, s := range c.subs[:3] {
			queries = append(queries, "?subscription_id="+s, "?subscription_id="+s+"&status=void")
		}
		queries = append(queries, "?customer_id="+orgs[0].cust[0].ID, "?customer_id="+orgs[1].cust[0].ID)
		queries = append(queries, "?limit=0", "?limit=101", "?cursor=bad", "?limit=abc")
	}
	for _, c := range orgs {
		for _, q := range queries {
			for _, lim := range []int{1, 2, 7, 20, 100} {
				sep := "?"
				if len(q) > 0 {
					sep = "&"
				}
				path := "/v1/invoices" + q
				if q == "" {
					path += "?"
				} else {
					path += ""
				}
				path = fmt.Sprintf("%s%slimit=%d", path, sep, lim)
				if q == "" {
					path = fmt.Sprintf("/v1/invoices?limit=%d", lim)
				}
				cursor := ""
				for page := 0; page < 2000; page++ {
					p := path
					if cursor != "" {
						p += "&cursor=" + cursor
					}
					r := e.Do("GET", p, c.org.Key, nil)
					add(p, r)
					var body struct {
						NextCursor string `json:"next_cursor"`
					}
					_ = json.Unmarshal(r.Body.Bytes(), &body)
					if body.NextCursor == "" || r.Code != http.StatusOK {
						break
					}
					cursor = body.NextCursor
				}
			}
		}
	}
	if err := os.WriteFile(out, []byte(joinLines(log)), 0o644); err != nil {
		t.Fatal(err)
	}
	t.Logf("wrote %d responses", len(log))
}

func joinLines(ls []string) string {
	s := ""
	for _, l := range ls {
		s += l + "\n"
	}
	return s
}

var _ = time.Second

